package com.aistock.market.adminquery;

import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.common.adminmarket.AdminMarketQuery.*;import com.aistock.common.BusinessException;
import java.time.*;import java.sql.Timestamp;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class AdminMarketReadMysqlTest {
 static final Instant NOW=Instant.parse("2026-10-22T04:00:00Z");JdbcTemplate j;AdminMarketReadRepository repo;
 @BeforeEach void init(){j=new MarketDatabaseFixture().jdbc();repo=new AdminMarketReadRepository(j);}
 void stock(String id,String name){j.update("insert into instrument(instrument_id,ticker,display_name,demo_only)values(?,?,?,false)",id,id,name);}
 String version(String id,String provider,int n,Instant at){var v=UUID.randomUUID().toString();j.update("insert into market_data_version(version_id,instrument_id,provider,price_basis,status,quality,content_hash,source_payload_hash,fetched_at,published_at,coverage_start,coverage_end)values(?,?,?,'RAW','AVAILABLE','ROW_VALIDATED',?,?,?,?, '2026-10-19','2026-10-21')",v,id,provider,String.format("%064x",n),"f".repeat(64),Timestamp.from(at),Timestamp.from(at));return v;}
 void head(String id,String provider,String v){j.update("insert into instrument_data_head(instrument_id,provider,price_basis,version_id,revision,checked_at,last_error_code)values(?,?,'RAW',?,2,?,'SOURCE_UNAVAILABLE')",id,provider,v,Timestamp.from(NOW));}
 ListFilter list(String q,String provider,String state,int page,int size){return new ListFilter(q,provider,state,page,size);}
 Map<String,List<Map<String,Object>>> snapshot(){var s=new LinkedHashMap<String,List<Map<String,Object>>>();for(var table:List.of("instrument","instrument_data_head","market_data_version","market_daily_bar","market_calendar_day","market_ingestion_operation","market_refresh_receipt"))s.put(table,j.queryForList("select * from "+table+" order by 1,2"));return s;}
 @Test void includesMissingSourcesKeepsAvailableAndFailureAndProtectsReferences(){stock("SH600030","stock%_!");stock("SH600276","second");stock("SZ000002","third");var a=version("SH600030","baostock",1,NOW);var b=version("SH600030","tushare",2,NOW);head("SH600030","baostock",a);head("SH600030","tushare",b);head("SZ000002","baostock",null);var before=snapshot();var page=repo.heads(list(null,null,null,1,2),NOW);assertEquals(2,page.items().size());assertTrue(page.hasMore());assertEquals("AVAILABLE",page.items().get(0).headState());assertEquals("SOURCE_UNAVAILABLE",page.items().get(0).lastErrorCode());assertEquals(2,repo.heads(list(null,null,"NO_VERSION",1,20),NOW).items().size());assertEquals(3,repo.heads(list(null,"tushare",null,1,20),NOW).items().size());assertEquals(2,repo.heads(list("%",null,null,1,20),NOW).items().size());assertEquals(2,repo.heads(list("_",null,null,1,20),NOW).items().size());assertEquals(before,snapshot());var wrong=version("SH600276","baostock",3,NOW);j.update("update instrument_data_head set version_id=? where instrument_id='SZ000002'",wrong);var broken=repo.heads(list(null,null,"REFERENCE_ERROR",1,20),NOW).items().get(0);assertEquals("SZ000002",broken.instrumentId());assertNull(broken.coverageEnd());assertNull(broken.versionStatus());}
 @Test void keysetPaginationRemainsStableWhenNewVersionArrives(){stock("SH600030","first");var old=new HashSet<String>();for(int n=1;n<=30;n++)old.add(version("SH600030","baostock",n,NOW));var first=repo.versions("SH600030",new HistoryFilter(null,null,20),NOW);assertEquals(20,first.items().size());assertNotNull(first.nextCursor());var newId=version("SH600030","baostock",31,NOW.plusSeconds(1));var second=repo.versions("SH600030",new HistoryFilter(null,first.nextCursor(),20),NOW);assertEquals(10,second.items().size());assertNull(second.nextCursor());var observed=new HashSet<String>();first.items().forEach(x->assertTrue(observed.add(x.versionId())));second.items().forEach(x->assertTrue(observed.add(x.versionId())));assertEquals(old,observed);assertFalse(observed.contains(newId));}
 @Test void showsRejectedIngestionsWithoutInventingVersionsAndDoesNotReconcileReceipts(){stock("SH600030","first");for(int n=0;n<11;n++)j.update("insert into market_ingestion_operation(operation_id,request_hash,instrument_id,provider,state,error_code,created_at,finished_at)values(?,?,'SH600030','baostock','REJECTED','PRIVATE_DETAIL',?,?)","reject-"+n,"a".repeat(64),Timestamp.from(NOW),Timestamp.from(NOW));j.update("insert into market_refresh_receipt(operation_id,request_hash,instrument_id,target_date,lease_until,state,created_at)values('past',?,'SH600030','2026-10-21',?,'RUNNING',?)","a".repeat(64),Timestamp.from(NOW.minusSeconds(60)),Timestamp.from(NOW.minusSeconds(120)));var before=snapshot();var p=repo.versions("SH600030",new HistoryFilter(null,null,20),NOW);assertTrue(p.items().isEmpty());assertEquals(10,p.recentIngestions().size());assertTrue(p.ingestionsTruncated());assertEquals("UNKNOWN_ERROR",p.recentIngestions().get(0).errorCode());assertEquals("RUNNING",p.recentRefreshes().get(0).state());assertTrue(repo.versions("SH600030",new HistoryFilter("tushare",null,20),NOW).recentRefreshes().isEmpty());assertEquals(before,snapshot());}
 @Test void fixedVersionDiagnosticsUsesOwnCalendarAndPreservesAllRows(){stock("SH600030","first");stock("SH600276","second");var a=version("SH600030","baostock",1,NOW);var b=version("SH600030","baostock",2,NOW.plusSeconds(1));head("SH600030","baostock",b);for(var v:List.of(a,b)){for(int day=19;day<=21;day++)j.update("insert into market_calendar_day values(?,?,?)",v,LocalDate.of(2026,10,day),day<21||v.equals(b));for(int day=19;day<=20;day++)j.update("insert into market_daily_bar(version_id,trade_date,open_price,high_price,low_price,close_price,volume_shares,amount_yuan,trade_status) values(?,? ,10,12,9,11,100,1100,?)",v,LocalDate.of(2026,10,day),day==20?0:1);}var before=snapshot();var window=new DetailFilter(LocalDate.parse("2026-10-19"),LocalDate.parse("2026-10-21"));var old=repo.detail("SH600030",UUID.fromString(a),window,NOW);assertEquals("NO_RECORDED_ISSUES",old.diagnostics().state());assertEquals("1",old.diagnostics().suspendedRowDays());assertFalse(old.version().isCurrent());assertNull(old.version().headRevision());assertEquals("NEEDS_REVIEW",repo.detail("SH600030",UUID.fromString(b),window,NOW).diagnostics().state());assertEquals(before,snapshot());var e=assertThrows(BusinessException.class,()->repo.detail("SH600276",UUID.fromString(a),window,NOW));assertEquals(404,e.status().value());}
 @Test void registeredEmptyStockIsReadableButUnknownAndDemoAreNot(){stock("SH600030","first");assertTrue(repo.versions("SH600030",new HistoryFilter(null,null,20),NOW).items().isEmpty());assertThrows(BusinessException.class,()->repo.versions("SH600999",new HistoryFilter(null,null,20),NOW));assertTrue(repo.heads(list(null,null,null,1,20),NOW).items().stream().noneMatch(x->x.instrumentId().startsWith("DEMO")));}
}
